CREATE TABLE BASE_AI_AGENT_CONFIG (F_Id BIGINT PRIMARY KEY, F_AgentCode NVARCHAR(100) NOT NULL, F_Name NVARCHAR(200) NOT NULL, F_Description NVARCHAR(2000), F_AgentType NVARCHAR(50) NOT NULL, F_PromptTemplateId BIGINT, F_SystemPrompt NVARCHAR(MAX), F_ModelProvider NVARCHAR(50) DEFAULT 'deepseek', F_ModelName NVARCHAR(100) DEFAULT 'deepseek-chat', F_Temperature DECIMAL(3,2) DEFAULT 0.7, F_MaxTokens INT DEFAULT 4096, F_Config NVARCHAR(MAX), F_Enabled BIT NOT NULL DEFAULT 1, F_Sort INT DEFAULT 0, F_CreatorTime DATETIME NOT NULL DEFAULT GETDATE(), F_CreatorUserId BIGINT, F_ModifyTime DATETIME, F_ModifyUserId BIGINT, F_DeleteMark BIT NOT NULL DEFAULT 0, CONSTRAINT UQ_AGENT_CODE UNIQUE (F_AgentCode));
CREATE INDEX IX_AGENT_TYPE ON BASE_AI_AGENT_CONFIG(F_AgentType, F_DeleteMark);
CREATE TABLE BASE_AI_AGENT_SKILL (F_Id BIGINT PRIMARY KEY, F_AgentId BIGINT NOT NULL, F_SkillCode NVARCHAR(100) NOT NULL, F_Name NVARCHAR(200) NOT NULL, F_Description NVARCHAR(2000), F_SkillType NVARCHAR(50), F_Config NVARCHAR(MAX), F_Enabled BIT NOT NULL DEFAULT 1, F_CreatorTime DATETIME NOT NULL DEFAULT GETDATE(), F_CreatorUserId BIGINT, F_ModifyTime DATETIME, F_ModifyUserId BIGINT, F_DeleteMark BIT NOT NULL DEFAULT 0);
CREATE INDEX IX_SKILL_AGENT ON BASE_AI_AGENT_SKILL(F_AgentId, F_DeleteMark);
CREATE TABLE BASE_AI_MCP_CONFIG (F_Id BIGINT PRIMARY KEY, F_Name NVARCHAR(200) NOT NULL, F_Endpoint NVARCHAR(500) NOT NULL, F_Protocol NVARCHAR(20) NOT NULL DEFAULT 'sse', F_AuthType NVARCHAR(20), F_AuthConfig NVARCHAR(MAX), F_Status NVARCHAR(20) NOT NULL DEFAULT 'disconnected', F_LastTestTime DATETIME, F_LastTestResult NVARCHAR(2000), F_Enabled BIT NOT NULL DEFAULT 1, F_CreatorTime DATETIME NOT NULL DEFAULT GETDATE(), F_CreatorUserId BIGINT, F_ModifyTime DATETIME, F_ModifyUserId BIGINT, F_DeleteMark BIT NOT NULL DEFAULT 0);
INSERT INTO BASE_AI_AGENT_CONFIG (F_Id,F_AgentCode,F_Name,F_AgentType,F_ModelProvider,F_ModelName,F_SystemPrompt,F_Enabled,F_Sort,F_CreatorTime) VALUES (100000001,'requirement-analyst','需求分析师','requirement-analyst','deepseek','deepseek-chat','你是一位资深的企业级软件需求分析师，精通 JNPF 低代码平台。',1,1,GETDATE());
